			Model:             row.ID,
			Harness:           row.Harness,
			Provider:          row.Provider,
			ProviderType:      row.ProviderType,
			EndpointName:      row.EndpointName,
			EndpointBaseURL:   row.EndpointBaseURL,
			ServerInstance:    row.ServerInstance,
